'use strict';
const $=s=>document.querySelector(s),$$=s=>Array.from(document.querySelectorAll(s));
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const C=DemoConfig,A=DemoAdapter;let operation='generate',current=null,busy=false,db={records:[],reviews:[]};
try{const s=JSON.parse(localStorage.getItem(C.storageKey)||'null');if(s&&Array.isArray(s.records)&&Array.isArray(s.reviews))db=s;}catch{}
const business=()=>$('#business').value,admin=()=>$('#identity').value==='admin',user=()=>admin()?'演示管理员':'演示成员';
function notify(t){$('#toast').textContent=t;}
function persist(){try{localStorage.setItem(C.storageKey,JSON.stringify(db));return true;}catch{notify('浏览器保存失败，请下载结果；刷新可能丢失。');return false;}}
function show(p){['creator','result','history','reviews'].forEach(x=>$('#'+x+'-page').classList.toggle('hidden',x!==p));$$('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===p));if(p==='history')renderHistory();if(p==='reviews')renderReviews();window.scrollTo(0,0);}
function sources(ss){return ss.map(s=>'<article class="source-card"><h3>'+esc(s.title)+'</h3><p>'+esc(s.text)+'</p><small>'+esc(s.locator)+'</small><p><span class="tag">实际用于演示</span></p><p class="muted">'+esc(s.usage)+'</p></article>').join('');}
function assessment(a){return !a?'':'<div class="score-card"><h3>学问忠实度</h3><span class="tag">'+esc(a.fidelity.level)+'</span><p>'+esc(a.fidelity.reason)+'</p></div><div class="score-card"><h3>表达贴近度</h3><span class="tag">'+esc(a.expression.level)+'</span><p>'+esc(a.expression.reason)+'</p></div><h3>逐句诊断（示例）</h3>'+a.issues.map(x=>'<p>“'+esc(x.fragment)+'”</p><p class="muted">'+esc(x.suggestion)+' · '+esc(x.source)+'</p>').join('');}
function saveVersion(content,why){current.versions.push({version:current.version,content:current.content});current.version++;current.modifications++;current.content=content;current.updatedAt=new Date().toISOString();current.lastChange=why;persist();renderResult();}
function renderResult(){const r=current;if(!r)return;const own=r.owner===user(),approved=db.reviews.some(x=>x.recordId===r.id&&x.sourceVersion===r.version&&x.status==='approved');
$('#result-page').innerHTML='<section class="content-panel result-card"><header class="result-top"><div><p class="eyebrow">吉利根 · 流程演示</p><h1>'+(r.operation==='evaluate'?'评估完成':r.operation==='search'?'检索完成':'生成完成')+'</h1><span class="muted">'+esc(r.owner)+' · 第 '+r.version+' 版 · 已修改 '+r.modifications+' 次</span></div><div class="action-row"><button id="download" class="button ghost">下载结果</button>'+(own?'<button id="personal" class="button ghost">'+(r.liked?'取消个人标记':'标记个人优质')+'</button>':'')+'<button id="submit-team" class="button primary">'+(approved?'本版已纳入团队':admin()?'直接纳入团队参考':'提交团队审核')+'</button><button class="button ghost" data-page="history">历史成稿</button></div></header><div class="result-columns"><div><h2>'+(r.operation==='evaluate'?'两轴评价':r.operation==='search'?'演示检索结果':'业务成品')+'</h2>'+assessment(r.assessment)+(r.operation==='search'?sources(r.sources):'<textarea id="output" class="editable" aria-label="可编辑文案" '+(own?'':'readonly')+'>'+esc(r.content)+'</textarea>'+(own?'<div class="button-row"><button id="save-edit" class="button ghost">保存手动编辑</button></div>':'')+'<p class="muted">固定模拟结果，未调用真实AI。手动编辑后请保存。</p>')+'</div><aside><h2>本次参考</h2>'+sources(r.sources)+'<p class="muted">均为合成示例，不是吉利根原话。真实接入后显示课程、书籍、文案来源及实际采用情况。</p></aside></div>'+(own&&r.operation!=='search'?'<section class="revise"><h2>继续修改这篇文案</h2><p class="readonly-type">继承原任务与业务类型，不需要重新选择类型。</p><label class="field"><span class="field-label">本轮修改要求</span><textarea id="revision" placeholder="例如：减少说教，保留核心观点，结尾更自然"></textarea></label><div class="action-row"><button id="revise" class="button primary">按要求修改</button></div></section>':'')+'</section>';
$('#download').onclick=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([r.content+'\n\n## 来源说明\n'+r.sources.map(s=>s.title+' / '+s.locator+' / '+s.usage).join('\n')],{type:'text/markdown;charset=utf-8'}));a.download='吉利根-演示结果-v'+r.version+'.md';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);};
if($('#personal'))$('#personal').onclick=()=>{r.liked=!r.liked;persist();renderResult();notify('个人标记只影响本人，未自动进入团队参考。');};
$('#submit-team').disabled=approved;$('#submit-team').onclick=()=>{const pending=db.reviews.find(x=>x.recordId===r.id&&x.sourceVersion===r.version&&x.status==='pending');if(pending&&!admin()){notify('本版已提交，等待审核。');return;}if(pending){pending.status='approved';pending.reviewer=user();pending.reviewedAt=new Date().toISOString();}else db.reviews.unshift(A.snapshot(r,user(),admin()));persist();renderResult();notify(admin()?'已直接纳入演示团队参考，操作已记录。':'已提交不可变审核快照；个人标记保持不变。');};
if($('#save-edit'))$('#save-edit').onclick=()=>{saveVersion($('#output').value,'手动编辑');notify('已保存新版本，不覆盖已提交审核内容。');};
if($('#revise'))$('#revise').onclick=()=>{const revision=$('#revision').value.trim();if(!revision){notify('请填写本轮修改要求。');$('#revision').focus();return;}run({business:r.business,operation:'revise',material:$('#output').value,revision,retain:r.retain,scenario:'available'},r);};
$$('#result-page [data-page]').forEach(b=>b.onclick=()=>show(b.dataset.page));}
async function run(input,parent=null){if(busy)return;busy=true;$('#submit').disabled=true;show('result');$('#result-page').innerHTML='<div class="live-status" role="status"><span class="step">演示处理中</span><h1>正在整理材料与来源</h1><p class="muted">模拟检查规则与返回结果，没有调用真实AI。</p></div>';await new Promise(r=>setTimeout(r,650));const result=A.execute(input);busy=false;$('#submit').disabled=false;
if(result.status!=='completed'){$('#result-page').innerHTML='<div class="content-panel notice blocked"><p class="eyebrow">本次未生成内容</p><h1>'+({INSUFFICIENT_EVIDENCE:'依据不足',BRIDGE_OFFLINE:'执行服务离线',QUOTA_EXCEEDED:'额度不足'}[result.code]||'请补充输入')+'</h1><p>'+esc(result.reason)+'</p><p class="muted">未创建伪造成功记录，原输入保留。</p><button id="back-edit" class="button primary">返回修改输入</button></div>';$('#back-edit').onclick=()=>show('creator');return;}
if(parent){current=parent;saveVersion(result.content,input.revision);return;}
current={id:'demo-'+Date.now()+'-'+Math.random().toString(16).slice(2),business:input.business,owner:user(),operation:input.operation,title:input.material.slice(0,26),content:result.content,sources:result.sources,assessment:result.assessment,retain:input.retain||'',version:1,modifications:0,versions:[],liked:false,updatedAt:new Date().toISOString(),modelCalled:false};db.records.unshift(current);persist();renderResult();}
function renderHistory(){const q=$('#history-search').value.trim(),quality=$('#quality-filter').value;const all=A.visibleHistory(db.records,business(),user(),admin()),items=all.filter(x=>(!q||(x.title+x.content).includes(q))&&(quality!=='personal'||x.liked)&&(quality!=='team'||db.reviews.some(r=>r.recordId===x.id&&r.status==='approved')));$('#history-count').textContent='显示 '+items.length+' 条，本业务共 '+all.length+' 条 · 仅本地演示记录';$('#history-list').innerHTML=items.length?items.map(x=>'<article class="history-row"><div><h2>'+esc(x.title)+'</h2><p class="muted">成员：'+esc(x.owner)+' · 第 '+x.version+' 版 · '+esc(new Date(x.updatedAt).toLocaleString())+'</p><p>'+esc(x.content.slice(0,90))+'</p><span class="tag">'+(x.liked?'个人已标记':'个人未标记')+'</span>'+(db.reviews.some(r=>r.recordId===x.id&&r.status==='approved')?'<span class="tag">团队已纳入（审核快照）</span>':'')+'</div><button class="button ghost" data-open="'+x.id+'">查看文案</button></article>').join(''):'<div class="empty">暂无符合条件的记录。完成演示后会保存到这里。</div>';$$('[data-open]').forEach(b=>b.onclick=()=>{current=db.records.find(x=>x.id===b.dataset.open);show('result');renderResult();});}
const statusNames={pending:'待审核',approved:'已纳入团队参考',rejected:'已退回',revoked:'已撤销'};
function renderReviews(){const rs=db.reviews.filter(x=>x.business===business()&&(admin()||x.submitter===user()));$('#reviews-title').textContent=admin()?'内容审核':'我的提交';$('#reviews-list').innerHTML=rs.length?rs.map(x=>'<article class="review-row"><div><h2>'+esc(x.title)+'</h2><p>提交人：'+esc(x.submitter)+' · 第 '+x.sourceVersion+' 版</p><p class="muted">'+esc(x.content.slice(0,75))+'</p><span class="tag">'+statusNames[x.status]+'</span></div><button class="button ghost" data-review="'+x.id+'">查看内容'+(admin()?'与审核':'')+'</button></article>').join(''):'<div class="empty">暂无提交。个人标记不会自动进入审核队列。</div>';$$('[data-review]').forEach(b=>b.onclick=()=>openReview(db.reviews.find(x=>x.id===b.dataset.review)));}
function openReview(x){$('#review-detail').innerHTML='<h2>'+esc(x.title)+'</h2><p>提交人：'+esc(x.submitter)+' · 审核版本：'+x.sourceVersion+'</p><p class="muted">提交时间：'+esc(x.submittedAt)+' · '+statusNames[x.status]+'</p><div class="review-body">'+esc(x.content)+'</div><p>审核人：'+esc(x.reviewer||'待审核')+'</p>'+(admin()?'<div class="button-row">'+(x.status==='pending'?'<button class="button primary" data-decision="approved">审核通过并纳入</button><button class="button ghost" data-decision="rejected">退回</button>':x.status==='approved'?'<button class="button ghost" data-decision="revoked">撤销团队参考</button>':'')+'</div>':'');$$('[data-decision]').forEach(b=>b.onclick=()=>{x.status=b.dataset.decision;x.reviewer=user();x.reviewedAt=new Date().toISOString();persist();$('#review-dialog').close();renderReviews();notify('已保存演示审核结果。');});$('#review-dialog').showModal();}
$$('[data-page]').forEach(b=>b.onclick=()=>show(b.dataset.page));$$('[data-operation]').forEach(b=>b.onclick=()=>{operation=b.dataset.operation;$$('[data-operation]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));$('#submit').textContent={generate:'生成初稿',evaluate:'开始评估',search:'检索知识'}[operation];$('#material-label').innerHTML=(operation==='evaluate'?'待评估文案':operation==='search'?'检索关键词或选题':'原始素材或选题方向')+' <strong>必填</strong>';});
$('#sidebar-toggle').onclick=()=>{const c=$('#workspace').classList.toggle('sidebar-collapsed');$('#sidebar-toggle').setAttribute('aria-expanded',String(!c));$('#sidebar-toggle').setAttribute('aria-label',c?'展开左侧导航':'收起左侧导航');};
$('#fill-sample').onclick=()=>{$('#material').value=C.sample;$('#requirements').value='语气温和坚定，减少说教，结尾保留开放式问题。';$('#retain').value='先承认此刻的感受';$('#scenario').value='available';notify('已填入合成材料，不是吉利根原话。');};
$('#task-form').onsubmit=e=>{e.preventDefault();run({business:business(),operation,material:$('#material').value,requirements:$('#requirements').value,retain:$('#retain').value,scenario:$('#scenario').value});};
$('#business').onchange=()=>{current=null;$('#gilligan-form').classList.toggle('hidden',business()!=='gilligan');$('#robert-note').classList.toggle('hidden',business()==='gilligan');$('#fill-sample').disabled=business()!=='gilligan';show('creator');};
$('#identity').onchange=()=>{current=null;$('#review-nav').textContent=admin()?'内容审核':'我的提交';show('creator');notify('已切换演示身份，不是生产鉴权。');};
$('#history-search').oninput=renderHistory;$('#quality-filter').onchange=renderHistory;$('#close-dialog').onclick=()=>$('#review-dialog').close();
$$('.sidebar [data-page]').forEach(b=>{b.setAttribute('aria-label',({creator:'新建内容',history:'历史成稿',reviews:'提交与审核'})[b.dataset.page]);b.title=b.getAttribute('aria-label');});
